<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization__main">
      <div class="optimization__main-manu">
        <div class="optimization__manu-item">
          <ButtonUI
            svg="back-arrow-svg"
            buttonClass="btn--second"
            @action="rejectPublication"
          />
          <p class="optimization__manu-title" v-if="id !== 'new'">
            Редактирование Записей #{{ id }}
          </p>
          <p class="optimization__manu-title" v-else>Новая запись</p>
        </div>
        <div class="optimization__manu-item">
          <ButtonUI
            svg="info-svg"
            buttonClass="btn--second"
            @action="openMenu('Reference')"
          />
          <ButtonUI
            svg="templates-svg"
            text="Применить шаблон"
            buttonClass="btn--primary"
            @action="useTemplate"
          />
        </div>
      </div>
      <div class="optimization-option">
        <ul class="optimization-option__form">
          <li class="optimization-option__item">
            <span class="optimization-option__text">Раздел</span>
            <CustomSelect
              v-model="selectPartition"
              placeholder="Автомобили"
              :options="selectPartitions"
              @updateSort="sortCategory"
            />
          </li>
          <li class="optimization-option__item" v-if="selectPartition.code">
            <span class="optimization-option__text">URL</span>
            <CustomInput v-model="inputUrl" placeholder="URL" />
          </li>

          <li class="optimization-option__item" v-if="id !== 'new'">
            <span class="optimization-option__text">Созданно</span>
            <p>{{ createItem }}</p>
          </li>
          <li class="optimization-option__item" v-if="id !== 'new'">
            <span class="optimization-option__text">Изменено</span>
            <div class="optimization-option__item-btn">
              <span>{{ updateItem }}</span>
              <ButtonUI
                svg="history-svg"
                text="история изменений"
                v-if="historyChange"
                @action="openMenu('Log')"
                buttonClass="btn--second"
              />
            </div>
          </li>
        </ul>
      </div>
      <ul class="optimization-option__list-box" v-if="selectPartition.code">
        <li
          class="optimization-option__list-item"
          v-for="(sw, index) in switches"
          :key="index"
        >
          <CustomSwitcher v-model="sw.enabled" :text="sw.label" />
          <div class="optimization-option__item" v-if="sw.enabled">
            <span class="optimization-option__text">Точное значение</span>

            <CheckboxUI v-model="sw.checkbox" />
            <CustomInput
              v-if="sw.checkbox"
              v-model="sw.name"
              :error="sw.error"
              :placeholder="sw.label"
            />
            <span v-if="sw && sw.enabled && error"
              >один из фильтров должен инметь точное названиие</span
            >
          </div>
          <OptimizatinFilterForm
            v-if="firstActiveIndex === index"
            :from="switches"
            :activForm="sw"
            :inputData="inputDataList[index]"
            :listСities="listСities"
            :validateModel="validateModel"
            @updateSort="handleUpdateSort"
            @update:inputData="updateInputData(index, $event)"
          />
        </li>
      </ul>

      <CustomMenu
        v-if="isMenuOpen"
        :name="menuName"
        :data="historyChange.data"
        @closing="isMenuOpen = false"
        @submit-action="chouseItem"
      />
      <div class="optimization-option__btn-box" v-if="isUpdateInForm">
        <ButtonUI
          :loading="loading"
          text="Сохранить"
          buttonClass="btn--primary"
          @action="saveForm"
        />
        <ButtonUI
          :loading="loading"
          text="Сохранить как шаблон"
          buttonClass="btn--second"
          @action="openMenu('Templates')"
        />
        <ButtonUI text="Отменить" buttonClass="btn--second" />
      </div>
    </div>
    <template v-if="showExitConfirm">
      <div class="modal-overlay">
        <div class="modal-window">
          <p class="modal-title">
            Вы уверены, что хотите покинуть страницу? Несохраненные данные будут
            потеряны.
          </p>
          <div class="modal-actions">
            <ButtonUI
              :buttonClass="`btn--second`"
              text="Всё равно покинуть"
              @click="confirmExit"
            />
            <ButtonUI text="Продолжить" @click="cancelExit" />
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch } from 'vue';

import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import ButtonUI from '@/components/UI/ButtonUI';
import CustomInput from '@/components/UI/CustomInput';
import CustomSwitcher from '@/components/UI/CustomSwitcher';
import CustomMenu from '@/components/Menu/CustomMenu.vue';
import OptimizatinFilterForm from '@/components/SEO/OptimizatinFilterForm';
import CheckboxUI from '@/components/UI/CheckboxUINEW';
import CustomSelect from '@/components/UI/CustomSelect';

import { FORMATER } from '@/composables/formater.js';

import {
  getHistoryChanges,
  checkItem,
  getAttributeValues,
  updateItemSeoFilter,
  addItemSeoFilter,
} from '@/services/apiTableAdmin.js';

import { isEqual, cloneDeep } from 'lodash';
import { useValidate } from '@/composables/useValidate.js';

import { getFilterOption } from '@/services/apiClient.js';
import { useCityStore } from '@/store/city.js';

import { useRoute, useRouter } from 'vue-router';

const route = useRoute();
const router = useRouter();

const citiesStore = useCityStore();

const title = ref('SEO фильтров');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const isMenuOpen = ref(false);
const menuName = ref('');
const listСities = ref([]);
const seoItem = ref('');
const createItem = ref('');
const updateItem = ref('');
const inputUrl = ref('');
const historyChange = ref('');

const oldModelSwitch = ref(null);
const oldinputDataList = ref(null);
const isUpdateInForm = ref(null);
const filteredSwitches = ref('');

const inputDataList = ref(null);
const loading = ref(false);
const error = ref(false);
const showExitConfirm = ref(false);
const validateModel = ref({
  city: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  noindex: {
    value: false,
    error: false,
    success: false,
  },
  url: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  description: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  title: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  h1: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  header: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  footer: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  keywords: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  seoText: {
    value: '',
    error: false,
    success: false,
    validateType: 'empty',
  },
  location: {
    value: '',
    error: false,
    success: false,
  },
});
const id = route.params.id;
const category = route.params.sectionid;
const titleToLabelMap = {
  is_amount: 'Цена',
  is_brand: 'Марка',
  is_car_body_type: 'Тип кузова',
  is_color: 'Цвет',
  is_condition: 'Состояние',
  is_drive: 'Привод',
  is_engine_type: 'Тип двигателя',
  is_equipment: 'Оборудование',
  is_id: 'Идентификатор',
  is_model: 'Модель',
  is_state: 'Состояние',
  is_transmission: 'Коробка передач',
  is_year: 'Год',
  //  если необходимо, можно добавить другие значения
};

const switches = ref([]);
const selectPartition = ref({});
const selectPartitions = ref(null);
const indexActiveform = ref('');
const firstActiveIndex = computed(() => {
  return switches.value.findIndex((s) => s.enabled);
});

const getParametrQRL = async () => {
  const data = await getFilterOption();
  if (id !== 'new') {
    historyChange.value = await getHistoryChanges(id);
    seoItem.value = await checkItem(id);
    createItem.value = FORMATER('date', seoItem.value.data.created_at, '||');
    updateItem.value = FORMATER('date', seoItem.value.data.updated_at, '||');
    inputUrl.value = seoItem.value.data.url.url;
  }
  await citiesStore.getСities();
  listСities.value = citiesStore.getSelectOption;
  const attributeValues = await getAttributeValues();
  switches.value = attributeValues?.data?.map((item) => {
    const label = titleToLabelMap[item.title] || item.title;
    return {
      label: label,
      checkbox: false,
      enabled: false,
      id: item.id,
      title: item.title,

      mark: {
        input: '',
        checkbox: true,
        name: '',
        error: false,
        success: false,
        validateType: 'empty',
      },
    };
  });
  inputDataList.value = switches.value.map(() => ({
    city: null,
    noindex: false,
    url: '',
    description: '',
    title: '',
    h1: '',
    header: '',
    footer: '',
    keywords: '',
    seoText: '',
    location: '',
  }));
  oldinputDataList.value = cloneDeep(inputDataList.value);

  selectPartitions.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
  if (category) {
    selectPartition.value = selectPartitions.value.find(
      (el) => el.code === category
    );
  }
  if (!seoItem.value) {
    return;
  }
  const filterForAttribute = seoItem.value.data.accurate_value;

  const filterArray = Array.isArray(filterForAttribute)
    ? filterForAttribute
    : [filterForAttribute];
  switches.value.forEach((item) => {
    item.enabled = filterArray.includes(item.title);
  });

  updateEnabled(switches, filterForAttribute);
  // oldModelSwitch.value = cloneDeep(oldModel.value);

  updateCurrentFrom();
};

const chouseItem = (item) => {
  seoItem.value = item;
  const filterForAttribute = seoItem.value.data.accurate_value;
  const filterArray = Array.isArray(filterForAttribute)
    ? filterForAttribute
    : [filterForAttribute];
  switches.value.forEach((item) => {
    item.enabled = filterArray.includes(item.title);
  });

  updateEnabled(switches, filterForAttribute);
  updateCurrentFrom();
};
const updateEnabled = (firstArray, secondArray) => {
  let isAssigned = false;
  secondArray.forEach((secondItem) => {
    firstArray.value.forEach((firstItem, index) => {
      if (firstItem.title === secondItem.attribute) {
        switches.value[index].enabled = true;
        switches.value[index].checkbox = true;
        switches.value[index].name = secondItem.value;
        if (!isAssigned) {
          indexActiveform.value = index;
          isAssigned = true;
        }
        return;
      }
    });
  });
  oldModelSwitch.value = cloneDeep(switches.value);
};

const updateCurrentFrom = () => {
  const currentForm = inputDataList.value[indexActiveform.value];
  const currentData = seoItem.value.data;
  currentForm.description = currentData.description;
  currentForm.footer = currentData.footer;
  currentForm.h1 = currentData.h1;
  currentForm.header = currentData.header;
  currentForm.keywords = currentData.keywords;
  currentForm.noindex = !!currentData.is_no_index;
  currentForm.seoText = currentData.seo_text;
  currentForm.title = currentData.title;
  currentForm.url = currentData.url.url_parameter_id;

  oldinputDataList.value = cloneDeep(inputDataList.value);
};
const updateCheck = () => {
  filteredSwitches.value = switches.value.filter((sw) => sw.enabled && sw.name);
  if (
    !isEqual(inputDataList.value, oldinputDataList.value) ||
    !isEqual(switches.value, oldModelSwitch.value)
  ) {
    return (isUpdateInForm.value = true);
  } else return (isUpdateInForm.value = false);
};

const updateInputData = (index, newValue) => {
  inputDataList.value[index] = newValue;
  indexActiveform.value = index;
  updateCheck();
};

const useTemplate = () => {
  const currentForm = inputDataList.value[indexActiveform.value];
  const formData = new FormData();

  if (filteredSwitches.value[0].title) {
    formData.append('filter_for_attribute', filteredSwitches.value[0].title);
    formData.append('description', currentForm.description);
    formData.append('footer', currentForm.footer);
    formData.append('h1', currentForm.h1);
    formData.append('header', currentForm.header);
    formData.append('keywords', currentForm.keywords);
    formData.append('is_no_index', currentForm.is_no_index ? '1' : '0');
    formData.append('seo_text', currentForm.seoText);
    formData.append('title', currentForm.title);
    formData.append('section_id', selectPartition.value.code);
    filteredSwitches.value.forEach((el, index) => {
      formData.append(`accurate_value[${index}][attribute]`, el.title);
      formData.append(`accurate_value[${index}][value]`, el.name);
    });
    if (currentForm.city) {
      formData.append('city_id', currentForm.city.code);
    } else formData.append('is_no_indicate_city', 1);
    loading.value = true;
    const res = updateItemSeoFilter(id, formData);
    if (res) {
      loading.value = false;
    }
  }
};
const saveForm = () => {
  const currentForm = inputDataList.value[indexActiveform.value];
  const formData = new FormData();

  validateModel.value.description.value = currentForm?.description;
  validateModel.value.h1.value = currentForm?.h1;
  validateModel.value.footer.value = currentForm?.footer;
  validateModel.value.header.value = currentForm?.header;
  validateModel.value.keywords.value = currentForm?.keywords;
  validateModel.value.seoText.value = currentForm?.seoText;
  validateModel.value.title.value = currentForm?.title;
  validateModel.value.noindex.value = currentForm?.is_no_index;
  const isValidateStatus = useValidate([
    validateModel.value.description,
    validateModel.value.h1,
    validateModel.value.footer,
    validateModel.value.header,
    validateModel.value.keywords,
    validateModel.value.seoText,
    validateModel.value.title,
    validateModel.value.noindex,
  ]);
  if (!isValidateStatus) return;

  if (filteredSwitches?.value[0]?.title) {
    formData.append('filter_for_attribute', filteredSwitches.value[0].title);
    formData.append('description', currentForm.description);
    formData.append('footer', currentForm.footer);
    formData.append('h1', currentForm.h1);
    formData.append('header', currentForm.header);
    formData.append('keywords', currentForm.keywords);
    formData.append('is_no_index', currentForm.is_no_index ? '1' : '0');
    formData.append('seo_text', currentForm.seoText);
    formData.append('title', currentForm.title);
    formData.append('section_id', selectPartition.value.code);
    filteredSwitches.value.forEach((el, index) => {
      formData.append(`accurate_value[${index}][attribute]`, el.title);
      formData.append(`accurate_value[${index}][value]`, el.name);
    });
    loading.value = true;
    if (currentForm.city) {
      formData.append('city_id', currentForm.city.code);
    } else formData.append('is_no_indicate_city', 1);
    if (id === 'new') {
      const res = addItemSeoFilter(formData);
      loading.value = false;

      if (res.success !== false) {
        router.back();
      }
    } else {
      const res = updateItemSeoFilter(id, formData);
      loading.value = false;
      if (res.success !== false) {
        router.back();
      }
    }
  } else {
    error.value = 'введите точное значение';
  }
};
const openMenu = (name) => {
  menuName.value = name;
  isMenuOpen.value = true;
};
const rejectPublication = () => {
  if (isUpdateInForm.value) {
    showExitConfirm.value = true;
  } else {
    router.back();
  }
};

const confirmExit = () => {
  showExitConfirm.value = false;
  router.back();
};

const cancelExit = () => {
  showExitConfirm.value = false;
};
onMounted(() => {
  getParametrQRL();
});
watch(
  switches,
  () => {
    updateCheck();
  },
  { deep: true }
);
</script>

<style scoped lang="scss">
.optimization {
  margin: 16px 24px 16px 24px;
  display: flex;
  flex-direction: column;
  width: calc(100% - 50px);
  &__header {
    margin-bottom: 20px;
  }
  @media (max-width: 1024px) {
    height: calc(100vh - 60px);
    margin-top: 85px;
  }

  &__main {
    box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
    // margin: 16px 12px 16px 0px;
    padding: 12px 24px;
    flex-direction: column;
    min-height: calc(100vh - 120px);

    &-manu {
      display: flex;
      justify-content: space-between;
    }
  }
  &__manu-item {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  &__manu-title {
    font-size: 16px;
    font-weight: 700;
    color: #003bce;
  }

  &-option {
    display: flex;
    flex-direction: column;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 16px 0;
    padding: 12px 24px;
    &__list-item {
      padding: 12px 0;
      border-top: 1px solid #d6d6d6;
    }
    &__btn-box {
      padding: 12px 0;
      border-top: 1px solid #d6d6d6;
    }
    @media (max-width: 1024px) {
      margin: 16px 0;
    }

    &__btn-box {
      display: flex;
      gap: 16px;
      align-items: center;
    }
    &__title-box {
      display: flex;
      justify-content: space-between;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      width: 100%;
      &-btn {
        display: flex;
        align-self: center;
        span {
          align-self: center;
        }
      }
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
    &__more {
      display: flex;
      align-items: center;
      justify-content: space-between;
      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      &-info {
        color: #3366ff;
      }
    }
  }
  &-form {
    max-width: 600px;
    box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
    border-radius: 4px;
    margin: 16px 12px 16px 0px;
  }
}
</style>
