<script setup>
import { ref, watch, defineEmits, defineProps } from 'vue';
import CheckboxUI from '@/components/UI/CheckboxUI';
import CustomSelectSearch from '@/components/UI/CustomSelectSearch';
import CustomInput from '@/components/UI/CustomInput';
import CutomTextArea from '@/components/UI/CutomTextArea';

const emit = defineEmits(['updateSort', 'update:inputData']);

const props = defineProps({
  from: Object,
  activForm: Object,
  inputData: Object,
  listСities: Object,
  validateModel: Object,
});

const localInputData = ref({ ...props.inputData });

const selectOption = (option) => {
  emit('updateSort', option.value);
};

watch(
  localInputData,
  (newValue) => {
    emit('update:inputData', newValue);
  },
  { deep: true }
);
</script>

